1	'use client';
2	
3	import { AnimatePresence, motion, useReducedMotion } from 'framer-motion';
4	import { useEffect, useState } from 'react';
5	import styles from './hero.module.css';
6	
7	const PHRASES = ['Ownership Driven', 'Without Hiring', 'On Demand'] as const;
8	
9	export function Typewriter() {
10	  const [index, setIndex] = useState(0);
11	  const prefersReducedMotion = useReducedMotion();
12	
13	  useEffect(() => {
14	    if (prefersReducedMotion) return;
15	    const interval = setInterval(() => {
16	      setIndex((prev) => (prev + 1) % PHRASES.length);
17	    }, 2400);
18	    return () => clearInterval(interval);
19	  }, [prefersReducedMotion]);
20	
21	  if (prefersReducedMotion) {
22	    return (
23	      <span
24	        className={`${styles['animate-span']} ${styles['typewriterContainer']}`}
25	      >
26	        {PHRASES[index]}
27	      </span>
28	    );
29	  }
30	
31	  return (
32	    <span
33	      aria-live="polite"
34	      aria-atomic="true"
35	      className={styles['typewriterContainer']}
36	    >
37	      <AnimatePresence mode="wait">
38	        <motion.span
39	          key={index}
40	          className={`${styles['animate-span']} ${styles['typewriterWord']}`}
41	          initial={{ opacity: 0, y: 10 }}
42	          animate={{ opacity: 1, y: 0 }}
43	          exit={{ opacity: 0, y: -10 }}
44	          transition={{ duration: 0.28, ease: 'easeInOut' }}
45	        >
46	          {PHRASES[index]}
47	        </motion.span>
48	      </AnimatePresence>
49	    </span>
50	  );
51	}
