3	import { useState } from "react";
4	import { z } from "zod";
5	import styles from "./contact-form-section.module.css";
6	
7	/* ── Schema ─────────────────────────────────────────────────── */
8	const ContactSchema = z.object({
9	  firstName: z.string().min(1, "First name is required"),
10	  lastName: z.string().min(1, "Last name is required"),
11	  email: z.string().min(1, "Email is required").email("Enter a valid email"),
12	  phone: z.string().optional(),
13	  inquiryType: z.string().min(1, "Please select an option"),
14	  message: z.string().optional(),
15	});
16	
17	type ContactFields = z.infer<typeof ContactSchema>;
18	type FieldErrors = Partial<Record<keyof ContactFields, string>>;
19	type FormStatus = "idle" | "submitting" | "success" | "error";
20	
21	const INITIAL: ContactFields = {
22	  firstName: "",
23	  lastName: "",
24	  email: "",
25	  phone: "",
26	  inquiryType: "",
27	  message: "",
28	};
29	
30	const INQUIRY_OPTIONS = [
31	  { value: "new-project", label: "Start a New Project" },
32	  { value: "agency-partnership", label: "Agency Partnership" },
33	  { value: "technical-account-support", label: "Technical or Account Support" },
34	  { value: "team", label: "Join Our Team" },
35	  { value: "general-inquiry", label: "General Inquiry" },
36	];
37	
38	/* ── Component ──────────────────────────────────────────────── */
39	export function ContactFormSection() {
40	  const [fields, setFields] = useState<ContactFields>(INITIAL);
41	  const [errors, setErrors] = useState<FieldErrors>({});
42	  const [status, setStatus] = useState<FormStatus>("idle");
43	
44	  function validateField(name: keyof ContactFields, value: string) {
45	    const result = ContactSchema.safeParse({ ...fields, [name]: value });
46	    if (!result.success) {
47	      const fieldError = result.error.flatten().fieldErrors[name];
48	      setErrors((prev) => ({
49	        ...prev,
50	        [name]: fieldError?.[0] ?? undefined,
51	      }));
52	    } else {
53	      setErrors((prev) => ({ ...prev, [name]: undefined }));
54	    }
55	  }
56	
57	  function handleChange(
58	    e: React.ChangeEvent<
59	      HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement
60	    >
61	  ) {
62	    const { name, value } = e.target;
63	    setFields((prev) => ({ ...prev, [name]: value }));
64	  }
65	
66	  function handleBlur(
67	    e: React.FocusEvent<
68	      HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement
69	    >
70	  ) {
71	    const { name, value } = e.target;
72	    validateField(name as keyof ContactFields, value);
73	  }
74	
75	  async function handleSubmit(e: React.FormEvent<HTMLFormElement>) {
76	    e.preventDefault();
77	    if (status === "submitting") return;
78	
79	    const result = ContactSchema.safeParse(fields);
80	    if (!result.success) {
81	      const fieldErrors = result.error.flatten().fieldErrors;
82	      const mapped: FieldErrors = {};
83	      for (const [k, v] of Object.entries(fieldErrors)) {
84	        const key = k as keyof ContactFields;
85	        if (v?.[0]) mapped[key] = v[0];
86	      }
87	      setErrors(mapped);
88	      return;
89	    }
90	
91	    setStatus("submitting");
92	    try {
93	      // Server action stub — logs and returns success
94	      await new Promise<void>((resolve) => setTimeout(resolve, 800));
95	      setStatus("success");
96	      setFields(INITIAL);
97	      setErrors({});
98	    } catch {
99	      setStatus("error");
100	    }
101	  }
102	
103	  return (
104	    <section className={styles.section} aria-label="Contact form">
105	      <div className={styles.container}>
106	        {/* aria-live region for screen readers */}
107	        <div
108	          role="status"
109	          aria-live="polite"
110	          aria-atomic="true"
111	          className={styles.srOnly}
112	        >
113	          {status === "success"
114	            ? "Your message has been sent successfully."
115	            : status === "error"
116	            ? "Something went wrong. Please try again."
117	            : ""}
118	        </div>
119	
120	        {status === "success" ? (
121	          <div className={styles.successMsg}>
122	            Thank you! Your submission has been received!
123	            <br />
124	            Our team will get back to you within 12-24hrs.
125	          </div>
126	        ) : (
127	          <>
128	            <h3 className={styles.heading}>Send us a message.</h3>
129	
130	            <form
131	              onSubmit={handleSubmit}
132	              className={styles.form}
133	              noValidate
134	              aria-label="Send a message"
135	            >
136	              {/* First Name + Last Name */}
137	              <div className={styles.rowTwo}>
138	                <div className={styles.field}>
139	                  <div className={styles.labelRow}>
140	                    <label htmlFor="firstName" className={styles.label}>
141	                      First Name
142	                    </label>
143	                    <span className={styles.required} aria-hidden="true">
144	                      *
145	                    </span>
146	                  </div>
147	                  <input
148	                    id="firstName"
149	                    name="firstName"
150	                    type="text"
151	                    placeholder="John"
152	                    maxLength={256}
153	                    value={fields.firstName}
154	                    onChange={handleChange}
155	                    onBlur={handleBlur}
156	                    required
157	                    aria-required="true"
158	                    aria-invalid={!!errors.firstName}
159	                    aria-describedby={
160	                      errors.firstName ? "firstName-error" : undefined
161	                    }
162	                    className={styles.input}
163	                  />
164	                  {errors.firstName && (
165	                    <p
166	                      id="firstName-error"
167	                      className={styles.fieldError}
168	                      role="alert"
169	                    >
170	                      {errors.firstName}
171	                    </p>
172	                  )}
173	                </div>
174	
175	                <div className={styles.field}>
176	                  <div className={styles.labelRow}>
177	                    <label htmlFor="lastName" className={styles.label}>
178	                      Last Name
179	                    </label>
180	                    <span className={styles.required} aria-hidden="true">
181	                      *
182	                    </span>
183	                  </div>
184	                  <input
185	                    id="lastName"
186	                    name="lastName"
187	                    type="text"
188	                    placeholder="Smith"
189	                    maxLength={256}
190	                    value={fields.lastName}
191	                    onChange={handleChange}
192	                    onBlur={handleBlur}
193	                    required
194	                    aria-required="true"
195	                    aria-invalid={!!errors.lastName}
196	                    aria-describedby={
197	                      errors.lastName ? "lastName-error" : undefined
198	                    }
199	                    className={styles.input}
200	                  />
201	                  {errors.lastName && (
202	                    <p
203	                      id="lastName-error"
204	                      className={styles.fieldError}
205	                      role="alert"
206	                    >
207	                      {errors.lastName}
208	                    </p>
209	                  )}
210	                </div>
211	              </div>
212	
213	              {/* Email + Phone */}
214	              <div className={styles.rowTwo}>
215	                <div className={styles.field}>
216	                  <div className={styles.labelRow}>
217	                    <label htmlFor="email" className={styles.label}>
218	                      Email
219	                    </label>
220	                    <span className={styles.required} aria-hidden="true">
221	                      *
222	                    </span>
223	                  </div>
224	                  <input
225	                    id="email"
226	                    name="email"
227	                    type="email"
228	                    placeholder="email@example.com"
229	                    maxLength={256}
230	                    value={fields.email}
231	                    onChange={handleChange}
232	                    onBlur={handleBlur}
233	                    required
234	                    aria-required="true"
235	                    aria-invalid={!!errors.email}
236	                    aria-describedby={
237	                      errors.email ? "email-error" : undefined
238	                    }
239	                    className={styles.input}
240	                  />
241	                  {errors.email && (
242	                    <p
243	                      id="email-error"
244	                      className={styles.fieldError}
245	                      role="alert"
246	                    >
247	                      {errors.email}
248	                    </p>
249	                  )}
250	                </div>
251	
252	                <div className={styles.field}>
253	                  <label htmlFor="phone" className={styles.label}>
254	                    Phone
255	                  </label>
256	                  <input
257	                    id="phone"
258	                    name="phone"
259	                    type="tel"
260	                    placeholder="+1 (123) 456 7890"
261	                    maxLength={256}
262	                    value={fields.phone}
263	                    onChange={handleChange}
264	                    onBlur={handleBlur}
265	                    className={styles.input}
266	                  />
267	                </div>
268	              </div>
269	
270	              {/* Inquiry Type */}
271	              <div className={styles.field}>
272	                <div className={styles.labelRow}>
273	                  <label htmlFor="inquiryType" className={styles.label}>
274	                    What Are You Looking For?
275	                  </label>
276	                  <span className={styles.required} aria-hidden="true">
277	                    *
278	                  </span>
279	                </div>
280	                <select
281	                  id="inquiryType"
282	                  name="inquiryType"
283	                  value={fields.inquiryType}
284	                  onChange={handleChange}
285	                  onBlur={handleBlur}
286	                  required
287	                  aria-required="true"
288	                  aria-invalid={!!errors.inquiryType}
289	                  aria-describedby={
290	                    errors.inquiryType ? "inquiryType-error" : undefined
291	                  }
292	                  className={styles.select}
293	                >
294	                  <option value="">Select an option...</option>
295	                  {INQUIRY_OPTIONS.map((opt) => (
296	                    <option key={opt.value} value={opt.value}>
297	                      {opt.label}
298	                    </option>
299	                  ))}
300	                </select>
301	                {errors.inquiryType && (
302	                  <p
303	                    id="inquiryType-error"
304	                    className={styles.fieldError}
305	                    role="alert"
306	                  >
307	                    {errors.inquiryType}
308	                  </p>
309	                )}
310	              </div>
311	
312	              {/* Message */}
313	              <div className={styles.field}>
314	                <label htmlFor="message" className={styles.label}>
315	                  Message
316	                </label>
317	                <textarea
318	                  id="message"
319	                  name="message"
320	                  placeholder="Enter your message..."
321	                  maxLength={5000}
322	                  value={fields.message}
323	                  onChange={handleChange}
324	                  onBlur={handleBlur}
325	                  className={styles.textarea}
326	                />
327	              </div>
328	
329	              {/* Form-level error */}
330	              {status === "error" && (
331	                <p className={styles.errorMsg} role="alert">
332	                  Oops! Something went wrong while submitting the form. Please
333	                  try again or email us directly.
334	                </p>
335	              )}
336	
337	              <div>
338	                <button
339	                  type="submit"
340	                  className={styles.submitBtn}
341	                  disabled={status === "submitting"}
342	                >
343	                  {status === "submitting" ? "Please wait..." : "Send Messsage"}
344	                </button>
345	              </div>
346	            </form>
347	          </>
348	        )}
349	      </div>
350	    </section>
351	  );
352	}
