12	function BetaPopup({ onClose }: { onClose: () => void }) {
13	  const firstFocusRef = useRef<HTMLButtonElement>(null);
14	  const modalRef = useRef<HTMLDivElement>(null);
15	
16	  // Body scroll lock
17	  useEffect(() => {
18	    const prev = document.body.style.overflow;
19	    document.body.style.overflow = "hidden";
20	    return () => {
21	      document.body.style.overflow = prev;
22	    };
23	  }, []);
24	
25	  // Escape key close
26	  useEffect(() => {
27	    function handleKey(e: KeyboardEvent) {
28	      if (e.key === "Escape") onClose();
29	      // Focus trap
30	      if (e.key === "Tab" && modalRef.current) {
31	        const focusable = Array.from(
32	          modalRef.current.querySelectorAll<HTMLElement>(
33	            'a[href], button:not([disabled]), input, textarea, select, [tabindex]:not([tabindex="-1"])'
34	          )
35	        );
36	        if (!focusable.length) return;
37	        const first = focusable[0];
38	        const last = focusable[focusable.length - 1];
39	        if (e.shiftKey) {
40	          if (document.activeElement === first) {
41	            e.preventDefault();
42	            last.focus();
43	          }
44	        } else {
45	          if (document.activeElement === last) {
46	            e.preventDefault();
47	            first.focus();
48	          }
49	        }
50	      }
51	    }
52	    document.addEventListener("keydown", handleKey);
53	    return () => document.removeEventListener("keydown", handleKey);
54	  }, [onClose]);
55	
56	  // Auto-focus close button on mount
57	  useEffect(() => {
58	    firstFocusRef.current?.focus();
59	  }, []);
60	
61	  return (
62	    <div
63	      className={betaStyles["betaPopupOverlay"]}
64	      onClick={(e) => { if (e.target === e.currentTarget) onClose(); }}
65	      aria-modal="true"
66	      role="dialog"
67	      aria-label="Beta access modal"
68	    >
69	      <div className={betaStyles["betaPopupModal"]} ref={modalRef}>
70	        <div className={betaStyles["popupLeftPanel"]}>
71	          <div className={betaStyles["popupBadge"]}>
72	            <div className={betaStyles["popBadgeTxt"]}>{"🔒"} Exclusive Access</div>
73	          </div>
74	          <h2 className={betaStyles["whiteHeading"]}>Private Beta Pricing</h2>
75	          <div className={betaStyles["whatsIncluded"]}>WHAT&apos;S INCLUDED</div>
76	          <div className={betaStyles["customPlanDlexdivNoWrap"]}>
77	            {["Beta pricing locked in", "Priority onboarding — live in 12 hours", "14-day satisfaction guarantee", "Pause or cancel anytime"].map((b) => (
78	              <div key={b} className={betaStyles["whiteLiIcon"]}>
79	                <div className={betaStyles["liCheckSky"]}>
80	                  <Image src="/images/webflow/Group-1.svg" alt="" width={19} height={19} className={betaStyles["circleTick"]} />
81	                </div>
82	                <p className={betaStyles["paragraphSmallWhiteSmallFont"]}>{b}</p>
83	              </div>
84	            ))}
85	          </div>
86	        </div>
87	        <div className={betaStyles["popupRightPanel"]}>
88	          <div className={betaStyles["eyebrowText"]}>Founding Partner Pricing</div>
89	          <h3 className={betaStyles["popMainHd"]}><strong>Start Your First Month with Beta Access</strong></h3>
90	          <p className={`${betaStyles["paragraph"]} ${betaStyles["paragraphSmallFont"]}`}>
91	            Join Boldteq&apos;s private beta and experience our agency delivery infrastructure at founding pricing — before public launch moves to standard rates.
92	          </p>
93	          <div className={betaStyles["popupUrgencyCard"]}>
94	            <div className={betaStyles["redDot"]} />
95	            <div className={betaStyles["redRightTxt"]}>Only <strong className={betaStyles["skyBold"]}>15 agencies</strong> will be accepted in this beta round</div>
96	          </div>
97	          <Link href="/book-a-demo" className={betaStyles["skyButton"]} onClick={onClose}>{"🚀"} Join the Beta</Link>
98	          <button type="button" className={betaStyles["popupSkip"]} onClick={onClose}>I&apos;ll wait for the public launch</button>
99	        </div>
100	        <button type="button" ref={firstFocusRef} aria-label="Close beta modal" className={betaStyles["popupCloseBtn"]} onClick={onClose}>
101	          <div className={betaStyles["closeTxt"]}>{"✕"}</div>
102	        </button>
103	      </div>
104	    </div>
105	  );
106	}
